record.field:
{
    "properties": {
        "partner_id": {
            "type": "number",
            "description": "ID of the partner (customer) for which the quotation is created"
        },
        "product_ids": {
            "type": "array",
            "description": "Array of product IDs for the quotation. Each product ID corresponds to the quantity at the same index in product_quantities",
            "items": {
                "type": "number"
            }
        },
        "product_quantities": {
            "type": "array",
            "description": "Array of product quantities for the quotation. Each quantity corresponds to the product ID at the same index in product_ids",
            "items": {
                "type": "number"
            }
        }
    },
    "required": ["partner_id", "product_ids", "product_quantities"],
    "type": "object"
}

{
    "properties": {
        "order_id": {
            "type": "number",
            "description": "ID of the created quotation"
        },
        "message_id": {
            "type": "number",
            "description": "ID of the message from the customer"
        }
    },
    "required": ["order_id", "message_id"],
    "type": "object"
}

{
    "properties": {
        "product_name": {
            "type": "string",
            "description": "Name of the product to search for"
        }
    },
    "required": ["product_name"],
    "type": "object"
}

{
    "properties": {
        "partner_name": {
            "type": "string",
            "description": "Name of the partner to search for"
        }
    },
    "required": ["partner_name"],
    "type": "object"
}
